function tokenFields(){return `${field('참고 자료 한도 · 추정 토큰',`<input data-setting="contextBudget" type="number" min="1000" max="1000000" value="${s.contextBudget}">`)}${field('전체 입력 최대 · 추정 토큰',`<input data-setting="inputMaxTokens" type="number" min="1000" max="1000000" value="${s.inputMaxTokens}">`)}${field('최대 출력 요청 · 토큰',`<input data-setting="maxTokens" type="number" min="512" max="200000" value="${s.maxTokens}">`)}<p class="hint">Short 약 2,000 / Middle 약 6,000 / Long 약 10,000 토큰. 최대 출력 요청은 목표보다 넉넉하게 잡아 주세요. HTML 코드와 추론도 한도를 사용할 수 있어요. 모델·연결의 실제 지원 한도가 우선하며 20만을 모두 지원하는 것은 아니에요.</p><p class="hint">입력은 지침·자료·이전 결과·이번 요청을 합쳐 검사해요. 추정치는 실제 모델 토크나이저와 다를 수 있어요. 참고 자료 한도를 넘으면 캐릭터·요약·세계관 같은 고정 자료는 유지하고 오래된 대화부터 자동으로 제외해요. 전체 입력 한도도 과거 대화를 추가로 줄여 맞추며, 과거 대화를 모두 제외해도 고정 자료·프리셋·이전 결과가 한도를 넘을 때만 중단해요. 본편 프리셋 모드도 오래된 본편 대화부터 자동으로 줄여요.</p>`;}
function viewerControls(visual=false){const input=(key,label,min,max,step=1)=>field(label,`<input type="number" data-setting="${key}" min="${min}" max="${max}" step="${step}" value="${s[key]}">`);const fonts=[['original','원본'],['system','시스템'],['sans','고딕'],['serif','명조'],['mono','고정폭']];return `${visual?`<label class="check"><input type="checkbox" data-setting="visualScripts" ${s.visualScripts?'checked':''}>격리된 HTML 상호작용 실행 (JS)</label><p class="hint">끄면 정적 화면만 표시해요. JS 화면의 번역 전환은 처음부터 다시 열려요. PNG 저장은 현재 화면 상태를 캡처해요.</p><label class="check"><input type="checkbox" data-setting="visualOverride" ${s.visualOverride?'checked':''}>HTML 읽기 설정 덮어쓰기</label>`:''}<div class="viewer-controls">${input(visual?'visualSize':'viewerSize','크기',10,28)}${field('글꼴',select(visual?'visualFont':'viewerFont',fonts))}${visual?'':input('viewerWidth','장평 (%)',75,125)}${input(visual?'visualSpacing':'viewerSpacing','자간 (px)',-2,6,.1)}${input(visual?'visualLine':'viewerLine','행높이',1,3,.05)}</div>${visual?'<p class="hint">기본은 HTML 원본 스타일을 유지해요. 덮어쓰기를 켜야 위 설정이 적용돼요.</p>':''}`;}
function translationSettings(){const builtin=s.activeTranslationPresetId===C.BUILTIN_TRANSLATION_ID;return `<h2>번역</h2>${field('번역용 API 연결',select('translationConnectionId',[['','생성용 연결과 동일'],...connections.map(c=>[c.id,c.name+' · '+(c.model||c.provider)])]))}${field('번역할 언어',`<input data-setting="translationLanguage" value="${E(s.translationLanguage)}" placeholder="한국어, English…">`)}${field('번역 최대 출력 요청 · 토큰',`<input type="number" data-setting="translationMaxTokens" min="512" max="200000" value="${s.translationMaxTokens}">`)}<p class="hint">최대 200,000까지 설정할 수 있어요. 모델 지원 한도가 우선해요. 긴 결과는 나누어 번역하므로 각 요청에 적용되는 한도예요. HTML은 텍스트만 번역하고 태그·스타일을 유지해요. 코드·스타일 블록은 번역하지 않아요. JS 안에서 만들어지는 문구는 번역 대상에서 제외돼요.</p>${field('번역 지침 프리셋',`<select id="translation-preset-select"><option value="${C.BUILTIN_TRANSLATION_ID}" ${builtin?'selected':''}>기본 · 내장</option>${s.translationPresets.map(p=>opt(p.id,p.name,s.activeTranslationPresetId)).join('')}</select>`)}<div class="preset-manage-actions"><button id="translation-preset-clone">${builtin?'복제해서 새 프리셋':'새 프리셋으로 복제'}</button>${builtin?'':`<button id="translation-preset-save" class="primary">저장</button><button id="translation-preset-cancel">변경 취소</button><button id="translation-preset-rename">이름 변경</button><button id="translation-preset-delete" class="danger-action">삭제</button>`}</div>${field('번역 지침 · 이름 표기와 말투 등',`<textarea id="translation-prompt-editor" rows="7" maxlength="12000" ${builtin?'readonly':''}>${E(builtin?SideExtras.TRANSLATE:translationPresetText())}</textarea>`)}<p id="translation-preset-status" class="hint">${translationPresetDirty()?'저장하지 않은 변경 사항이 있어요.':'저장된 지침을 사용 중이에요.'}</p><p class="hint">사용자 지침은 저장 버튼을 눌러 반영해요. 내장 지침은 잠겨 있어요. 복제하면 직역·말투 보존·고유명사 처리처럼 목적별 번역 프리셋을 만들 수 있어요. 항목 ID와 JSON 응답 형식은 구조 보존을 위해 별도로 적용돼요.</p>`;}
