async function backgroundStore(){if(!backgroundDB)backgroundDB=await new Promise((resolve,reject)=>{const q=indexedDB.open('side-b-backgrounds-v1',1);q.onupgradeneeded=()=>q.result.createObjectStore('backgrounds',{keyPath:'id'});q.onsuccess=()=>resolve(q.result);q.onerror=()=>reject(q.error);q.onblocked=()=>reject(Error('다른 창에서 배경 보관함을 사용 중이에요.'));});return backgroundDB;}
