 for(const text of visible){ctx.fillText(text,x,y);y+=lineHeight;}
 ctx.font=`${metaSize}px ${font}`;y=h-margin-metaLines*metaLine;for(const text of [...title,...author]){ctx.fillText(text,x,y);y+=metaLine;}
