function launcherViewport(){return {w:Math.max(1,window.innerWidth||document.documentElement.clientWidth||1),h:Math.max(1,window.innerHeight||document.documentElement.clientHeight||1)};}
function launcherCoords(){if(!Number.isFinite(s.launcherX)||!Number.isFinite(s.launcherY))return null;const {w,h}=launcherViewport(),size=launcherSize(),margin=6,maxX=Math.max(margin,w-size-margin),maxY=Math.max(margin,h-size-margin);return {left:margin+s.launcherX*Math.max(0,maxX-margin),top:margin+s.launcherY*Math.max(0,maxY-margin)};}
