function applyLauncherPosition(button=$('launcher')){if(!button)return;const pos=launcherCoords();if(!pos){for(const k of ['left','top','right','bottom'])button.style.removeProperty(k);return;}button.style.left=Math.round(pos.left)+'px';button.style.top=Math.round(pos.top)+'px';button.style.right='auto';button.style.bottom='auto';}
