 const [messages,cards,players,lore]=await Promise.all([
 target&&options.referenceMode!=='summary'?get('/chats/'+encodeURIComponent(target)+'/messages'+(options.scope==='all'?'':'?limit='+Number(options.scope)),signal):[],
 Promise.all(ids.map(id=>get('/characters/'+encodeURIComponent(id),signal))),
 Promise.all(pids.map(key=>{const i=key.indexOf(':');return get((key.slice(0,i)==='character'?'/characters/':'/characters/personas/')+encodeURIComponent(key.slice(i+1)),signal);})),
 Promise.all(options.loreIds.map(async lid=>{const entries=await get('/lorebooks/'+encodeURIComponent(lid)+'/entries',signal),overrides=H.parseObject(H.parseObject(chat.metadata).entryStateOverrides);return {name:lorebooks.find(l=>l.id===lid)?.name||lid,entries:entries.filter(e=>options.loreEntries[lid]?options.loreEntries[lid].includes(e.id):(overrides[e.id]?.enabled??H.truth(e.enabled))).map(e=>({name:e.comment||e.name||'',content:e.content}))};}))]);
 const ctx=H.context({chat,cards,personas:players,messages,lore},options);
 let preset=null;if(options.presetId){const mode=chat.mode||'roleplay';let pid=options.presetId,sourceChat=chat;if(pid==='__chat'){const meta=H.parseObject(chat.metadata);if(mode==='conversation'&&typeof meta.customSystemPrompt==='string'&&meta.customSystemPrompt.trim()){preset={prompt:{messages:[{role:'system',content:meta.customSystemPrompt.trim()}]},parameters:{},mode};}else{const listed=new Set(presets.map(p=>p.id)),fallback=presets.find(p=>H.truth(p.isDefault))?.id||'',connectionPreset=connections.find(c=>c.id===cid)?.promptPresetId||'',candidateIds=(mode==='roleplay'?[connectionPreset,chat.promptPresetId,fallback]:[chat.promptPresetId,fallback]).filter(Boolean),resolved=presets.length?candidateIds.find(id=>listed.has(id)):candidateIds[0];pid=resolved||'';if(!pid&&mode==='game'&&((typeof meta.gameSystemPrompt==='string'&&meta.gameSystemPrompt.trim())||(typeof meta.customGmPrompt==='string'&&meta.customGmPrompt.trim()))){preset={prompt:{messages:[{role:'system',content:[meta.gameSystemPrompt,meta.customGmPrompt].filter(x=>typeof x==='string'&&x.trim()).map(x=>x.trim()).join('\n\n')}]},parameters:{},mode};}}}if(!preset){if(!pid)throw new Error('적용할 프리셋을 찾지 못했어요. 프리셋을 직접 선택해 주세요.');const full=await get('/prompts/'+encodeURIComponent(pid)+'/full',signal);if(options.presetId!=='__chat')sourceChat={...chat,metadata:{},promptPresetId:pid};preset=SideSelectedPreset.compile(full,ctx,sourceChat,mode);}}
