function showCompletedResult(record,translation,originChat,signal){
 if(!alive||!opened||signal?.aborted||chatId!==originChat)return false;
 closeFeature();referencesOpen=false;current=record;continuationMode=null;page='create';mobilePane='result';viewEpoch++;
 translationShown=translation;translationDraft=null;raw=false;editing=false;expanded=record.mode==='visual';return true;
}
